-- Reglas tributarias de Chile y Argentina en borrador, con fuente. Ninguna está verificada: requieren revisión de un contador.
insert into public.ai_knowledge (kind, area, country_code, topic, title, summary, source_name, source_url, license, lang, status) values
('tax_rule','impuestos','CL','iva','IVA en Chile: tasa general',
$k$En Chile el Impuesto al Valor Agregado (IVA) consiste en un recargo de 19 % sobre el precio final que determina el vendedor de un bien o servicio, según la explicación educativa del Servicio de Impuestos Internos (SII). La norma base es el Decreto Ley 825 sobre Impuesto a las Ventas y Servicios. Qué operaciones están afectas, exentas o no afectas, y los plazos de declaración mensual, deben confirmarse en el SII o con un contador.$k$,
'SII Chile, SII Educa: tipos de impuestos en Chile','https://www.sii.cl/siieduca/aprende-con-nosotros/tipos-de-impuestos-en-chile.html',
'Material informativo del Servicio de Impuestos Internos de Chile; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.','es','draft'),
('tax_rule','impuestos','CL','idpc','Impuesto de Primera Categoría en Chile: tasas por régimen',
$k$El Impuesto de Primera Categoría (IDPC) grava las rentas de empresas y la tasa depende del régimen. Según la tabla de tasas del SII, el régimen general del artículo 14 letra A de la Ley de la Renta tiene una tasa de 27 %, y el régimen Pro Pyme general (artículo 14 letra D número 3) aplicó una tasa reducida de 12,5 % en 2025 y 2026, como rebaja transitoria; la tasa permanente del Pro Pyme es de 25 %. Una fuente de apoyo indica que la rebaja a 12,5 % rige para 2025 a 2027 y luego sube a 15 % en 2028 y vuelve a 25 % en 2029, salvo prórroga legal. Además, un análisis de KPMG de 2026 describe una reforma tributaria que reduciría gradualmente la tasa de 27 % a 23 % desde el 1 de enero de 2027 y unificaría las tasas: debe confirmarse si fue aprobada antes de usar cualquiera de esos valores.$k$,
'SII Chile, ¿Qué tasas de Impuesto de Primera Categoría se aplican desde 1977 en adelante?','https://www.sii.cl/preguntas_frecuentes/declaracion_renta/001_140_4708.htm',
'Material informativo del Servicio de Impuestos Internos de Chile y fuentes de apoyo (KPMG, Rankia); no declaran licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.','es','draft'),
('tax_rule','contabilidad','CL','boleta_electronica','Boleta y factura electrónica en Chile',
$k$En Chile la boleta electrónica de ventas y servicios es obligatoria desde 2021, y el SII refuerza que la emisión y entrega de la boleta es obligatoria en cada compra. La factura electrónica es obligatoria desde 2018, según una fuente de apoyo. El SII ofrece un sistema gratuito de emisión de boletas electrónicas en su sitio web, que permite emitirlas desde cualquier dispositivo móvil. Los contribuyentes que emiten boleta electrónica deben enviar una copia de cada una al SII y la boleta debe informar por separado el monto del IVA. Quién está obligado y desde cuándo en cada caso debe consultarse en las preguntas frecuentes del SII.$k$,
'SII Chile, Noticias y preguntas frecuentes sobre boleta electrónica','https://www.sii.cl/noticias/2025/200125noti01pcr.htm',
'Material informativo del Servicio de Impuestos Internos de Chile; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.','es','draft'),
('tax_rule','impuestos','AR','iva','IVA en Argentina: alícuotas',
$k$El Impuesto al Valor Agregado (IVA) en Argentina tiene una alícuota general de 21 %, establecida en el artículo 28 de la Ley de IVA, que se aplica a la mayoría de los bienes y servicios. Existe una alícuota reducida de 10,5 % para ciertos rubros, como la construcción de vivienda, medicina prepaga o transporte, y una alícuota incrementada de 27 % para telecomunicaciones y servicios públicos de gas, agua y energía prestados a usuarios comerciales o industriales. Si un bien o servicio no está en las listas de alícuota reducida, incrementada o exento, se aplica 21 %. El IVA a pagar es el débito fiscal menos el crédito fiscal. Las alícuotas provienen de fuentes de apoyo: confirmarlas en el texto de la Ley de IVA.$k$,
'Avalara VATlive y Yo Facturo: IVA en Argentina','https://www.avalara.com/vatlive/en/country-guides/south-america/argentina/argentina-vat-compliance-and-rates.html',
'Fuentes de apoyo; no declaran licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador y con la Ley de IVA.','es','draft'),
('tax_rule','impuestos','AR','monotributo','Monotributo en Argentina: categorías y valores que se actualizan',
$k$El Monotributo es el Régimen Simplificado para Pequeños Contribuyentes de ARCA (antes AFIP). Ordena a los contribuyentes en categorías de la A a la K según sus ingresos brutos anuales, y cada categoría tiene una cuota mensual fija. Los topes y las cuotas se actualizan periódicamente (ARCA publicó una tabla de valores de aplicación desde el 1 de agosto de 2026) y las fuentes consultadas dan topes distintos para 2026, por lo que esta entrada no incluye montos: deben leerse siempre en la tabla vigente de ARCA. Quien supera el tope de la categoría más alta pasa al régimen general de responsable inscripto, con IVA mensual y declaración de Ganancias.$k$,
'ARCA Argentina, valores del Monotributo (tabla vigente)','https://www.arca.gob.ar/transparencia/bitacora/2025.asp',
'Material informativo de ARCA y fuentes de apoyo (Lookuptax, Hacé Cuentas); no declaran licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.','es','draft'),
('tax_rule','contabilidad','AR','factura_electronica','Factura electrónica en Argentina (RG 5893/2026)',
$k$Según la Resolución General 5893 de 2026 de ARCA, los responsables inscriptos, exentos y no alcanzados por el IVA, junto con los adheridos al Monotributo, deben respaldar sus operaciones con comprobantes electrónicos o con Controlador Fiscal. La resolución extendió la obligación a quienes aún tenían excepciones: los monotributistas sociales y promovidos deben facturar electrónicamente desde el 1 de noviembre de 2026, y los no alcanzados por el IVA tienen plazo hasta marzo de 2027, sin poder usar controlador fiscal. Si el contribuyente no tiene punto de venta habilitado para factura electrónica, ARCA lo habilita para el monotributo. Los talonarios impresos solo se admiten ante contingencias. Cada caso debe confirmarse en la resolución y con un contador.$k$,
'ARCA, novedad sobre la obligación de emitir factura electrónica','https://servicioscf.afip.gob.ar/publico/sitio/contenido/novedad/ver.aspx?id=5881',
'Material informativo de ARCA y prensa especializada (iProfesional); no declaran licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.','es','draft');
